import React, { useContext, useState } from "react";
import noteContext from "../context/notes/noteContext";

const Noteitem = (props) => {
  const context = useContext(noteContext);
  const { deleteNote, duplicateNote, exportNote, printNote } = context;
  const { note, updateNote } = props;
  const [showFullContent, setShowFullContent] = useState(false);

  const handleDelete = () => {
    if (window.confirm('Are you sure you want to delete this note?')) {
      deleteNote(note._id);
      props.showAlert("Deleted Successfully", "success");
    }
  };

  const handleDuplicate = async () => {
    const success = await duplicateNote(note);
    if (success) {
      props.showAlert("Note duplicated successfully", "success");
    } else {
      props.showAlert("Failed to duplicate note", "danger");
    }
  };

  const handleExport = (format) => {
    exportNote(note, format);
    props.showAlert(`Note exported as ${format.toUpperCase()}`, "success");
  };

  const handlePrint = () => {
    printNote(note);
  };

  // Truncate content for preview
  const truncateText = (text, limit = 100) => {
    if (!text) return '';
    if (text.length <= limit) return text;
    return showFullContent ? text : text.substring(0, limit) + '...';
  };

  // Parse tags
  const tags = note.tag ? note.tag.split(',').map(tag => tag.trim()).filter(tag => tag) : [];

  // Count todo completion
  const todoStats = note.todoItems ? {
    total: note.todoItems.length,
    completed: note.todoItems.filter(todo => todo.completed).length
  } : { total: 0, completed: 0 };

  // Format date
  const formatDate = (dateString) => {
    if (!dateString) return '';
    return new Date(dateString).toLocaleString();
  };

  return (
    <div className="col-lg-4 col-md-6 col-sm-12">
      <div className="card my-3 h-100 note-card">
        <div className="card-header d-flex justify-content-between align-items-start">
          <h5 className="card-title mb-0 flex-grow-1">{note.title}</h5>
          
          {/* Action Dropdown */}
          <div className="dropdown">
            <button
              className="btn btn-link btn-sm text-muted"
              type="button"
              data-bs-toggle="dropdown"
              aria-expanded="false"
            >
              <i className="fas fa-ellipsis-v"></i>
            </button>
            <ul className="dropdown-menu dropdown-menu-end">
              <li>
                <button className="dropdown-item" onClick={() => updateNote(note)}>
                  <i className="fas fa-edit me-2"></i>Edit
                </button>
              </li>
              <li>
                <button className="dropdown-item" onClick={handleDuplicate}>
                  <i className="fas fa-copy me-2"></i>Duplicate
                </button>
              </li>
              <li><hr className="dropdown-divider" /></li>
              <li>
                <button className="dropdown-item" onClick={handlePrint}>
                  <i className="fas fa-print me-2"></i>Print
                </button>
              </li>
              <li>
                <button className="dropdown-item" onClick={() => handleExport('txt')}>
                  <i className="fas fa-file-alt me-2"></i>Export as TXT
                </button>
              </li>
              <li><hr className="dropdown-divider" /></li>
              <li>
                <button className="dropdown-item text-danger" onClick={handleDelete}>
                  <i className="fas fa-trash me-2"></i>Delete
                </button>
              </li>
            </ul>
          </div>
        </div>

        <div className="card-body d-flex flex-column">
          {/* Note Content */}
          <div className="note-content mb-3 flex-grow-1">
            <div 
              className="note-description"
              dangerouslySetInnerHTML={{ 
                __html: truncateText(note.description, 150) 
              }}
            />
            {note.description && note.description.length > 150 && (
              <button
                className="btn btn-link btn-sm p-0 mt-1"
                onClick={() => setShowFullContent(!showFullContent)}
              >
                {showFullContent ? 'Show less' : 'Show more'}
              </button>
            )}
          </div>

          {/* Tags */}
          {tags.length > 0 && (
            <div className="mb-3">
              {tags.map((tag, index) => (
                <span key={index} className="badge bg-primary me-1 mb-1">
                  <i className="fas fa-tag me-1"></i>{tag}
                </span>
              ))}
            </div>
          )}

          {/* Todo Items Preview */}
          {note.todoItems && note.todoItems.length > 0 && (
            <div className="mb-3">
              <div className="d-flex align-items-center mb-2">
                <i className="fas fa-tasks me-2 text-muted"></i>
                <small className="text-muted">
                  Todo: {todoStats.completed}/{todoStats.total} completed
                </small>
              </div>
              <div className="progress mb-2" style={{ height: '4px' }}>
                <div
                  className="progress-bar bg-success"
                  style={{ 
                    width: `${todoStats.total > 0 ? (todoStats.completed / todoStats.total) * 100 : 0}%` 
                  }}
                ></div>
              </div>
              <div className="todo-preview">
                {note.todoItems.slice(0, 3).map((todo, index) => (
                  <div key={index} className="d-flex align-items-center mb-1">
                    <i className={`fas ${todo.completed ? 'fa-check-circle text-success' : 'fa-circle text-muted'} me-2`}></i>
                    <small className={`${todo.completed ? 'text-decoration-line-through text-muted' : ''}`}>
                      {todo.text.length > 30 ? todo.text.substring(0, 30) + '...' : todo.text}
                    </small>
                  </div>
                ))}
                {note.todoItems.length > 3 && (
                  <small className="text-muted">+{note.todoItems.length - 3} more items</small>
                )}
              </div>
            </div>
          )}

          {/* Images Preview */}
          {note.images && note.images.length > 0 && (
            <div className="mb-3">
              <div className="d-flex align-items-center mb-2">
                <i className="fas fa-image me-2 text-muted"></i>
                <small className="text-muted">{note.images.length} image(s)</small>
              </div>
              <div className="d-flex flex-wrap">
                {note.images.slice(0, 4).map((image, index) => (
                  <img
                    key={index}
                    src={image.url}
                    alt={image.name}
                    className="me-1 mb-1 rounded"
                    style={{ width: '40px', height: '40px', objectFit: 'cover' }}
                  />
                ))}
                {note.images.length > 4 && (
                  <div 
                    className="d-flex align-items-center justify-content-center bg-light rounded"
                    style={{ width: '40px', height: '40px' }}
                  >
                    <small>+{note.images.length - 4}</small>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Attachments Preview */}
          {note.attachments && note.attachments.length > 0 && (
            <div className="mb-3">
              <div className="d-flex align-items-center">
                <i className="fas fa-paperclip me-2 text-muted"></i>
                <small className="text-muted">{note.attachments.length} attachment(s)</small>
              </div>
            </div>
          )}
        </div>

        {/* Card Footer */}
        <div className="card-footer bg-light">
          <div className="d-flex justify-content-between align-items-center">
            <div className="text-muted small">
              <div>
                <i className="fas fa-calendar-plus me-1"></i>
                {formatDate(note.createdAt || note.date)}
              </div>
              {note.updatedAt && note.updatedAt !== (note.createdAt || note.date) && (
                <div className="mt-1">
                  <i className="fas fa-edit me-1"></i>
                  {formatDate(note.updatedAt)}
                </div>
              )}
            </div>
            
            {/* Quick Actions */}
            <div className="btn-group btn-group-sm" role="group">
              <button
                className="btn btn-outline-primary btn-sm"
                onClick={() => updateNote(note)}
                title="Edit Note"
              >
                <i className="fas fa-edit"></i>
              </button>
              <button
                className="btn btn-outline-secondary btn-sm"
                onClick={handlePrint}
                title="Print Note"
              >
                <i className="fas fa-print"></i>
              </button>
              <button
                className="btn btn-outline-danger btn-sm"
                onClick={handleDelete}
                title="Delete Note"
              >
                <i className="fas fa-trash"></i>
              </button>
            </div>
          </div>
        </div>
      </div>

      <style jsx>{`
        .note-card {
          transition: transform 0.2s, box-shadow 0.2s;
          border: 1px solid #dee2e6;
        }
        .note-card:hover {
          transform: translateY(-2px);
          box-shadow: 0 4px 8px rgba(0,0,0,0.1);
        }
        .note-content {
          overflow-wrap: break-word;
        }
        .note-description {
          line-height: 1.5;
        }
        .todo-preview {
          font-size: 0.85rem;
        }
        .card-footer {
          font-size: 0.8rem;
        }
      `}</style>
    </div>
  );
};

export default Noteitem;
